interface Printable {
    // Compiler implicitly adds: public static final
    int DEFAULT_DPI = 300;
    String WATERMARK = "CONFIDENTIAL";

    // Compiler implicitly adds: public abstract
    void print();
    void setPaperSize(String size);
}

class Invoice implements Printable {
    private String invoiceNumber;
    private String paper = "A4";

    public Invoice(String invoiceNumber) {
        this.invoiceNumber = invoiceNumber;
    }

    // MUST be public! Cannot reduce visibility from interface's implicit public
    @Override
    public void print() {
        System.out.println("Printing Invoice #" + invoiceNumber + " at " + DEFAULT_DPI + " DPI [" + WATERMARK + "] on " + paper);
    }

    @Override
    public void setPaperSize(String size) {
        this.paper = size;
    }
}

public class InterfaceDemo {
    public static void main(String[] args) {
        // Interface reference pointing to concrete implementing object
        Printable doc = new Invoice("INV-2026-001");
        doc.setPaperSize("Letter");
        doc.print();

        // Accessing interface constants directly via interface name
        System.out.println("Standard DPI: " + Printable.DEFAULT_DPI);
    }
}

