practiceProblems.solutionCode:
interface RemoteControl {
    int MAX_VOLUME = 100;
    void powerOn();
    void setVolume(int level);
}

class Television implements RemoteControl {
    private int volume = 20;
    @Override
    public void powerOn() {
        System.out.println("TV powered on");
    }
    @Override
    public void setVolume(int level) {
        if (level <= MAX_VOLUME) {
            this.volume = level;
            System.out.println("Volume set to " + volume);
        }
    }
}

public class RemoteApp {
    public static void main(String[] args) {
        RemoteControl remote = new Television();
        remote.powerOn();
        remote.setVolume(45);
    }
}

interface Encryptor {
    String encrypt(String plainText);
}

class Rot13Encryptor implements Encryptor {
    @Override
    public String encrypt(String plainText) {
        return "[ROT13] " + plainText;
    }
}

class Base64MockEncryptor implements Encryptor {
    @Override
    public String encrypt(String plainText) {
        return "[B64] " + plainText;
    }
}

public class CryptoSuiteApp {
    public static void main(String[] args) {
        Encryptor[] suite = new Encryptor[] {
            new Rot13Encryptor(),
            new Base64MockEncryptor()
        };
        String sample = "HelloWorld";
        for (Encryptor e : suite) {
            System.out.println(e.encrypt(sample));
        }
    }
}

practiceProblems.problemStatement:
Build a media player interface from scratch:

1. Interface Playable:
   - Method 1: void play();
   - Method 2: void pause();

2. Implementing Classes:
   - Class PodcastEpisode: field title, constructor(title), play() prints 'Playing podcast episode: ' + title, pause() prints 'Paused podcast: ' + title
   - Class MovieStream: field title, constructor(title), play() prints 'Buffering 4K stream for: ' + title, pause() prints 'Paused movie: ' + title

Test in Main:
Playable podcast = new PodcastEpisode("Tech Talk #42"); podcast.play(); podcast.pause();
Playable movie = new MovieStream("Interstellar"); movie.play(); movie.pause();.

practiceProblems.solutionCode:
interface Playable {
    void play();
    void pause();
}

class PodcastEpisode implements Playable {
    private String title;
    public PodcastEpisode(String title) { this.title = title; }
    @Override
    public void play() {
        System.out.println("Playing podcast episode: " + title);
    }
    @Override
    public void pause() {
        System.out.println("Paused podcast: " + title);
    }
}

class MovieStream implements Playable {
    private String title;
    public MovieStream(String title) { this.title = title; }
    @Override
    public void play() {
        System.out.println("Buffering 4K stream for: " + title);
    }
    @Override
    public void pause() {
        System.out.println("Paused movie: " + title);
    }
}

public class MediaApp {
    public static void main(String[] args) {
        Playable p1 = new PodcastEpisode("Tech Talk #42");
        Playable p2 = new MovieStream("Interstellar");
        p1.play();
        p1.pause();
        p2.play();
        p2.pause();
    }
}

